import org.jfree.data.time.Second;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TimeSeries_createCopy_TriageGen1Test {

    private TimeSeries series;
    private RegularTimePeriod p1;
    private RegularTimePeriod p2;
    private RegularTimePeriod p3;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");

        // Create periods: p1 < p2 < p3
        Calendar cal = Calendar.getInstance();
        cal.set(2023, 0, 1, 10, 0, 0);
        p1 = new Second(cal.getTime());
        cal.add(Calendar.HOUR, 1);
        p2 = new Second(cal.getTime());
        cal.add(Calendar.HOUR, 1);
        p3 = new Second(cal.getTime());

        series.add(p1, 1.0);
        series.add(p2, 2.0);
        series.add(p3, 3.0);
    }

    @Test
    public void testCreateCopy_NullStart() {
        try {
            series.createCopy(null, p2);
            fail("Should have thrown IllegalArgumentException for null start");
        } catch (IllegalArgumentException e) {
            assertEquals("Null 'start' argument.", e.getMessage());
        } catch (CloneNotSupportedException e) {
            fail("Should not throw CloneNotSupportedException");
        }
    }














}

