public class TimeSeries_createCopy_TriageGen1Test {

    private TimeSeries series;
    private RegularTimePeriod p1;
    private RegularTimePeriod p2;
    private RegularTimePeriod p3;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");

        // Create periods: p1 < p2 < p3
        Calendar cal = Calendar.getInstance();
        cal.set(2023, 0, 1, 10, 0, 0);
        p1 = new Second(cal.getTime());
        cal.add(Calendar.HOUR, 1);
        p2 = new Second(cal.getTime());
        cal.add(Calendar.HOUR, 1);
        p3 = new Second(cal.getTime());

        series.add(p1, 1.0);
        series.add(p2, 2.0);
        series.add(p3, 3.0);
    }









    @Test
    public void testCreateCopy_RangeWithMissingPeriods() throws CloneNotSupportedException {
        // Create a period that isn't in the series but falls between items
        Calendar cal = Calendar.getInstance();
        cal.set(2023, 0, 1, 10, 30, 0);
        RegularTimePeriod midPeriod = new Second(cal.getTime());

        // Start is midPeriod (index < 0, should resolve to index 1)
        // End is midPeriod (index < 0, should resolve to index 0)
        // This case tests the getIndex logic where start/end are not in the series

        // Test: start is between p1 and p2, end is between p1 and p2
        // startIndex = getIndex(mid) -> -2. startIndex = -(-2+1) = 1.
        // endIndex = getIndex(mid) -> -2. endIndex = -2 + 1 - 1 = -2 (Wait, logic check)
        // Let's use a more predictable range for the branch coverage:

        // Test: start is exactly p1, end is a period that is before p1
        Calendar calBefore = Calendar.getInstance();
        calBefore.set(2022, 0, 1);
        RegularTimePeriod beforeP1 = new Second(calBefore.getTime());

        // endIndex < 0 scenario
        TimeSeries emptyCopy = series.createCopy(p1, beforeP1); 
        // This should trigger the start > end exception first.
    }






}

