    @Test
    public void testCreateCopy_SuccessfulSubrange() throws CloneNotSupportedException {
        // Test range that spans from an existing item to a non-existing item that falls after it
        Calendar cal = Calendar.getInstance();
        cal.set(2023, 0, 1, 10, 30, 0);
        RegularTimePeriod mid = new Second(cal.getTime()); // between p1 and p2

